import { LayoutDashboard, UsersRound, ListChecks, CalendarDays, Network, GraduationCap, BookOpen, ShoppingBag, Package, ChartNoAxesCombined, Users, Menu, X } from 'lucide-react';
import { Logo } from '@/components/brand/Logo';
